test('automatic polling hides transient approval and concurrent stale/manual responses cannot accept twice',async t=>{
  const controls={duplicateApproval:true},fixture=await setup(t,controls),races=[],observed=[];let started;
  controls.observeResponse=(_id,result)=>{if(result.action==='accept'){const saved=JSON.parse(readFileSync(join(fixture.directory,'productions',started.id+'.json'),'utf8'));assert.equal(saved.autoApproveArtwork,true);assert.equal(saved.generationAttempted,true);assert.equal(saved.status,'approval','the claim is durable before the native accept response');}};
  controls.afterApproval=()=>{races.push(fixture.manager.status(started.id).then(job=>{observed.push(job);assert.equal(job.autoApproveArtwork,true);assert.equal(job.status,'artwork','the ordinary client must keep polling while the accept is persisted');assert.equal(job.approval,undefined);return fixture.manager.approve(started.id,{approvalId:'stale-manual-token',action:'accept'});}).catch(error=>{assert.equal(error.statusCode,409);}));};
  started=await fixture.manager.start({...payload(),autoApproveArtwork:true});const ready=await finishWithoutApproval(fixture.manager,started.id);await Promise.all(races);assert.equal(ready.status,'ready',ready.message);assert.equal(observed.length,3);assert.equal(fixture.responses.length,3);assert.equal(fixture.calls.filter(call=>call.kind==='generation').length,3);
  const manual=await setup(t),manualJob=await manual.manager.start(payload()),pending=await finish(manual.manager,manualJob.id,{approve:false}),responses=await Promise.allSettled([manual.manager.approve(manualJob.id,{approvalId:pending.approval.id,action:'accept'}),manual.manager.approve(manualJob.id,{approvalId:pending.approval.id,action:'accept'})]);assert.equal(responses.filter(result=>result.status==='fulfilled').length,1);assert.equal(responses.find(result=>result.status==='rejected').reason.statusCode,409);assert.equal(manual.responses.length,1);assert.equal((await finish(manual.manager,manualJob.id)).status,'ready');assert.equal(manual.responses.length,3);
});

