test('sample production requires a real selected template before any provider check or inference',async t=>{
  let calls=0;const directory=await mkdtemp(join(tmpdir(),'studio-choice-test-'));t.after(()=>rm(directory,{recursive:true,force:true}));const unexpected=()=>{calls++;throw Error('No provider may run without a chosen template');},manager=createSlideProduction({directory,providers:{status:unexpected,checkModel:unexpected,infer:unexpected}});
  for(const conceptId of [undefined,'','unknown'])await assert.rejects(manager.start({...payload(),conceptId}),/choose.*template|select.*template/i);
  for(const autoApproveArtwork of ['true',1,null])await assert.rejects(manager.start({...payload(),autoApproveArtwork}),/automatic artwork or manual/);
  assert.equal(calls,0);assert.equal(manager.busy,false);
});

test('the selected template loads one skill and compact canonical sources and produces exactly three real sample images',async t=>{
  const names={editorial:'Quiet Editorial',studio:'Signal Studio',warm:'Warm Dimension'};
  for(const conceptId of Object.keys(names)){
    const fixture=await setup(t),requests=[];let manager,started;
    const providers={...fixture.providers,infer:async(_provider,prompt,schema,selected)=>{
      const {ids,sources,sample}=requestOf(prompt);assert.equal(sample,true);assert.deepEqual(ids,[conceptId]);
      assert.match(prompt,new RegExp('# '+names[conceptId]));for(const other of Object.keys(names).filter(other=>other!==conceptId))assert.ok(!prompt.includes('# '+names[other]),'only the chosen variation is loaded');
      assert.match(prompt,/80.?120 words/);assert.match(prompt,/EXACTLY3 sample pages/);assert.deepEqual(sources.map(source=>Object.keys(source).sort()),Array(2).fill(['audience','id','notes','title']));
      assert.deepEqual(sources,representativeSources(brief).map(({id,title,audience,notes})=>({id,title,audience,notes})));
      assert.deepEqual(selected,{model:'gpt-6.1-sol',reasoningEffort:'medium'});assert.equal(schema.properties.concepts.maxItems,1);assert.deepEqual(schema.properties.concepts.items.properties.conceptId.enum,[conceptId]);assert.equal(schema.properties.concepts.items.properties.slides.minItems,3);assert.equal(schema.properties.concepts.items.properties.slides.maxItems,3);requests.push(conceptId);
      const current=await manager.status(started.id);assert.equal(current.conceptId,conceptId);assert.equal(current.status,'planning');assert.equal(current.concepts.length,0);assert.match(current.message,new RegExp(names[conceptId]));assert.match(current.message,/3 sample slides/);assert.equal(fixture.calls.filter(call=>call.kind==='generation').length,0);
      return proposed(sources,ids,{sample});
    }};
    manager=createSlideProduction({providers,directory:fixture.directory,createSession:fixture.createSession,fetchFn:fixture.fetchFn});started=await manager.start({...payload(),conceptId});const ready=await finish(manager,started.id);
    assert.equal(ready.status,'ready',ready.message);assert.equal(ready.conceptId,conceptId);assert.deepEqual(requests,[conceptId]);assert.equal(ready.concepts.length,1);assert.equal(ready.concepts[0].slides.length,3);assert.equal(fixture.calls.filter(call=>call.kind==='generation').length,3);assert.equal(renderConceptSlides(brief,conceptId,{production:ready}).length,3);
    assert.equal(JSON.parse(await readFile(join(fixture.directory,'productions',ready.id+'.json'),'utf8')).conceptId,conceptId);
  }
});

test('three-page samples bind every page to real source content, retain order and reject missing, unknown or duplicate teaching pages',()=>{
  for(const sources of [representativeSources(brief).slice(0,1),representativeSources(brief)]){
    const valid=proposed(sources,['warm'],{sample:true}),bound=bindSlidePlans(valid,sources,['warm'],{sample:true})[0].slides;
    assert.equal(bound.length,3);assert.equal(new Set(bound.map(slide=>slide.id)).size,3);for(const slide of bound){const source=sources.find(source=>source.id===slide.sourceId);assert.equal(slide.sourceAudience,source.audience);assert.equal(slide.originalNotes,source.notes);assert.equal(slide.notes,source.notes);}
  }
  const sources=representativeSources(brief),valid=proposed(sources,['warm'],{sample:true});
  for(const mutate of [value=>value.concepts[0].slides.pop(),value=>value.concepts[0].slides[2].sourceId='synthetic-source',value=>value.concepts[0].slides.reverse(),value=>{for(const slide of value.concepts[0].slides)slide.sourceId=sources[0].id;},value=>value.concepts[0].slides[2].purpose=value.concepts[0].slides[1].purpose,value=>value.concepts[0].slides[2].artworkPrompt=value.concepts[0].slides[1].artworkPrompt]){const invalid=structuredClone(valid);mutate(invalid);assert.throws(()=>bindSlidePlans(invalid,sources,['warm'],{sample:true}),error=>error.planRepairable===true);}
});

test('AI plans and actual unique artwork are bound to three selected-template sample pages without mutating the manuscript',async t=>{
  const {manager,calls,responses}=await setup(t),raw=payload(),source=raw.brief.productDraft,started=await manager.start(raw);
  const pending=await finish(manager,started.id,{approve:false});assert.equal(pending.status,'approval');assert.equal(responses.length,0,'no image approval is synthesized');assert.match(pending.approval.prompt,/source-specific/);
  await assert.rejects(manager.approve(started.id,{approvalId:'stale',action:'accept'}),/no longer pending/);
  const result=await finish(manager,started.id);assert.equal(result.status,'ready');assert.equal(manager.busy,false);assert.equal(result.conceptId,'warm');assert.equal(result.concepts.length,1);assert.deepEqual(result.concepts[0].slides.map(slide=>slide.sourceId),['source-1','source-2','source-2']);
  const slides=result.concepts.flatMap(concept=>concept.slides);assert.equal(slides.length,3);assert.equal(new Set(slides.map(slide=>slide.artwork.id)).size,3);assert.equal(new Set(slides.map(slide=>slide.artwork.sha256)).size,3);assert.equal(calls.filter(call=>call.kind==='generation').length,3);assert.equal(responses.length,3);
  for(const slide of slides){const canonical=representativeSources(brief).find(source=>source.id===slide.sourceId);assert.equal(slide.sourceAudience,canonical.audience);assert.equal(slide.originalNotes,canonical.notes);assert.equal(slide.notes,canonical.notes);assert.equal(slide.artwork.quality,'preview','thumbnail provenance is labeled truthfully');assert.deepEqual([slide.artwork.width,slide.artwork.height],[128,96]);assert.ok((await manager.asset(slide.artwork.id)).bytes.length>50);}
  assert.equal(raw.brief.productDraft,source);assert.equal((await manager.start(raw)).id,result.id,'the same request never silently regenerates artwork');
  const native=await manager.resolve(result.id,brief,'warm');for(const slide of result.concepts[0].slides)assert.match(native.images[slide.artwork.id],/^data:image\/png;base64,/);
});

test('one-slide refinement creates only one new referenced image, keeps the original version and becomes the latest unchanged-template sample',async t=>{
  const fixture=await setup(t),{manager,calls}=fixture,raw={...payload(),conceptId:'editorial'},first=await finish(manager,(await manager.start(raw)).id),before=structuredClone(first),target=first.concepts[0].slides[1];
  const edit={...raw,productionId:first.id,refineSlideId:target.id,feedback:'Remove the baked title and column labels. Preserve the specific visitor journeys, palette and illustration treatment.'},started=await manager.start(edit);
  assert.notEqual(started.id,first.id,'an artwork correction must create a new version, not return the unchanged sample');assert.equal((await manager.start(edit)).id,started.id,'a duplicate click must reuse this exact edit');
  const ready=await finish(manager,started.id);assert.equal(ready.status,'ready',ready.message);assert.equal(ready.parentProductionId,first.id);assert.equal(ready.refineSlideId,target.id);assert.equal(ready.conceptId,'editorial');assert.equal(calls.filter(call=>call.kind==='plan').length,1,'there is no replanning');assert.equal(calls.filter(call=>call.kind==='generation').length,4,'only the selected fourth artwork is requested');
  const generations=calls.filter(call=>call.kind==='generation');for(const call of generations){assert.equal(call.user_intent,ARTWORK_USER_INTENT);assert.match(call.user_intent,/No words, letters, numbers, headings or captions/);}for(const call of generations.slice(0,3))assert.deepEqual(call.imageReferences,[]);assert.deepEqual(generations[3].imageReferences,[{type:'MEDIA',id:target.artwork.canvaMediaId}]);assert.equal(generations[3].aspectRatio,artworkAspectRatio(target));
  const slides=ready.concepts[0].slides;assert.equal(slides.length,3);assert.deepEqual(slides.map(slide=>slide.id),before.concepts[0].slides.map(slide=>slide.id));for(const index of [0,2])assert.deepEqual(slides[index],before.concepts[0].slides[index]);assert.notEqual(slides[1].artwork.id,target.artwork.id);assert.notEqual(slides[1].artwork.sha256,target.artwork.sha256);assert.equal(slides[1].sourceAudience,target.sourceAudience);assert.equal(slides[1].originalNotes,target.originalNotes);assert.equal(slides[1].notes,target.notes);assert.deepEqual(slides[1].composition,target.composition);assert.match(slides[1].artworkPrompt,/Remove the baked title/);
  assert.deepEqual(await manager.status(first.id),before,'the original sample and assets are retained');assert.ok((await manager.asset(target.artwork.id)).bytes.length>50);assert.equal((await manager.start(raw)).id,ready.id);assert.equal((await manager.start(edit)).id,ready.id);assert.equal(calls.filter(call=>call.kind==='generation').length,4);assert.equal(renderConceptSlides(brief,'editorial',{production:ready}).length,3);
  const restored=createSlideProduction({directory:fixture.directory,providers:{status(){throw Error('Never infer just to reopen the latest version');}}});assert.equal((await restored.start(raw)).id,ready.id);assert.equal((await restored.status(first.id)).id,first.id);
});

