  const deck=await finish(manager,(await manager.start({...payload(),mode:'deck',productionId:sample.id,approved:true})).id),saved=structuredClone(deck.concepts[0].slides);
  const expanded={...brief,productDraft:brief.productDraft+'\n\n## Leave a follow-up\n\nAssign the unanswered question and agree a follow-up date.\n\n### Presenter notes\n\nOriginal CHARLIE: never guess the missing answer.'};
