  assert.equal(await manager.sampleReady(deck.id,expanded,'warm'),true,'a prior ready deck is valid against its own saved coverage and unchanged retained source');
  await assert.rejects(manager.resolve(deck.id,expanded,'warm'),/source changed/,'native resolve still requires the complete current manuscript');
  const next=await finish(manager,(await manager.start({...payload(),brief:expanded,mode:'deck',productionId:deck.id,approved:true})).id);assert.equal(next.status,'ready',next.message);assert.equal(next.complete,true);assert.deepEqual(next.concepts[0].slides.slice(0,3),saved);assert.deepEqual(next.concepts[0].slides.map(slide=>slide.sourceId),['source-1','source-2','source-2','source-3']);assert.equal(calls.filter(call=>call.kind==='generation').length,4);assert.deepEqual(calls.filter(call=>call.kind==='plan').at(-1).sourceIds,['source-3']);assert.equal(renderConceptSlides(expanded,'warm',{production:next}).length,4);assert.equal(Object.keys((await manager.resolve(next.id,expanded,'warm')).images).length,4);
